def test_frontend_noncanonical_strided_add_pipeline_structure_and_runtime():
    """Frontend non-canonical strided map should not not get replaced by library
    nodes because we do not apply map tiling and run correctly."""
    sdfg = frontend_noncanonical_vadd_program.to_sdfg(simplify=True)
    count = apply_cutile_pipeline(
        sdfg,
        validate=True,
        apply_map_collapse_and_tiling=False,
    )
    assert count == 0

    state = sdfg.states()[0]
    map_entries = [n for n in state.nodes() if isinstance(n, nodes.MapEntry)]
    tasklets = [n for n in state.nodes() if isinstance(n, nodes.Tasklet)]
    assert len(map_entries) == 1
    assert len(tasklets) == 1

    # Ensure the strided/non-zero-start frontend range is still represented.
    map_range = str(map_entries[0].map.range)
    assert "1:13:2" in map_range
    assert "2:10" in map_range

    assert len(tasklets[0].in_connectors) == 2
    assert len(tasklets[0].out_connectors) == 1

    sdfg.expand_library_nodes()
    sdfg.validate()

    rng = np.random.default_rng(7003)
    a = rng.uniform(-5.0, 5.0, size=(13, 11)).astype(np.float64)
    b = rng.uniform(-5.0, 5.0, size=(13, 11)).astype(np.float64)
    c = rng.uniform(-2.0, 2.0, size=(13, 11)).astype(np.float64)

    expected = c.copy()
    expected[1:13:2, 2:10] = a[1:13:2, 2:10] + b[1:13:2, 2:10]

    sdfg(A=a, B=b, C=c)
    np.testing.assert_allclose(c, expected, rtol=0.0, atol=1e-12)


@pytest.mark.parametrize("tile_shape", [(10, 11), (16, 9)])
def test_frontend_large_prime_strided_add_with_nonmultiple_tile_shape(tile_shape):
    """Large prime-strided frontend map should remain correct after map tiling."""
    sdfg = frontend_large_prime_stride_vadd_program.to_sdfg(simplify=True)
    count = apply_cutile_pipeline(
        sdfg,
        validate=True,
        apply_map_collapse_and_tiling=True,
        tile_shape=tile_shape,
    )
    assert count >= 2

    lib_nodes = _frontend_library_nodes(sdfg)
    sym_nodes = [n for n in lib_nodes if isinstance(n, TileSymbolicMaskedOpLibraryNode)]
    assert sym_nodes
    assert all(n.mask_condition is not None for n in sym_nodes)

    sdfg.expand_library_nodes()
    sdfg.validate()

    rng = np.random.default_rng(7004)
    a = rng.uniform(-8.0, 8.0, size=(211, 197)).astype(np.float64)
    b = rng.uniform(-8.0, 8.0, size=(211, 197)).astype(np.float64)
    c = rng.uniform(-3.0, 3.0, size=(211, 197)).astype(np.float64)

    expected = c.copy()
    expected[2:209:3, 5:194:7] = a[2:209:3, 5:194:7] + b[2:209:3, 5:194:7]

    sdfg(A=a, B=b, C=c)
    np.testing.assert_allclose(c, expected, rtol=0.0, atol=1e-12)


